HSIC_RUN = '\n"""Run-bundle HSIC residual scan integration.\n\nSlice 18A consumes PIRS residual artifacts emitted by Slice 17B and performs a\nbounded residual-dependence scan against selected design-matrix covariates. It\nwrites HSIC scan artifacts and hypothesis rows but does not refit PIRS models,\nre-run EFG materialization, or mutate compile semantics.\n"""\n\nfrom __future__ import annotations\n\nimport json\nfrom datetime import datetime, timezone\nfrom pathlib import Path\nfrom typing import Any, Mapping, Sequence\n\nimport pyarrow as pa\nimport pyarrow.parquet as pq\n\nfrom pegasus.pirs.hsic import linear_hsic_statistic, permutation_p_value\n\n\nDEFAULT_MODEL_MANIFEST = Path("Tables") / "pirs_model_execution_manifest.json"\nDEFAULT_DESIGN_MANIFEST = Path("Tables") / "pirs_design_matrix_manifest.json"\nDEFAULT_RESIDUAL_VALUES = Path("Tables") / "pirs_residual_values.parquet"\nDEFAULT_DESIGN_MATRIX = Path("Tables") / "pirs_design_matrix.parquet"\nDEFAULT_HSIC_MANIFEST = Path("Tables") / "hsic_residual_scan_manifest.json"\nDEFAULT_HSIC_SCORES = Path("Tables") / "hsic_residual_scan_scores.parquet"\nHSIC_GATE_KEY = "hsic_residual_scan_gate"\nJSON_ATTACH_TARGETS: tuple[str, ...] = (\n    "RunConfig.json",\n    "P_vector.json",\n    "UserIntent.json",\n    "ReproducibilityManifest.json",\n)\n\n\nclass HSICResidualScanError(RuntimeError):\n    """Raised when HSIC residual scanning receives malformed run artifacts."""\n\n\ndef _now() -> str:\n    return datetime.now(timezone.utc).isoformat()\n\n\ndef _compact(value: Any) -> str:\n    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"), default=str)\n\n\ndef _load_json(path: Path) -> dict[str, Any]:\n    if not path.exists():\n        return {}\n    try:\n        payload = json.loads(path.read_text(encoding="utf-8"))\n    except json.JSONDecodeError:\n        return {}\n    return payload if isinstance(payload, dict) else {}\n\n\ndef _write_json(path: Path, payload: Mapping[str, Any]) -> Path:\n    path.parent.mkdir(parents=True, exist_ok=True)\n    path.write_text(json.dumps(dict(payload), ensure_ascii=False, sort_keys=True, indent=2, default=str), encoding="utf-8")\n    return path\n\n\ndef _read_rows(path: Path) -> list[dict[str, Any]]:\n    if not path.exists():\n        return []\n    return [dict(row) for row in pq.read_table(path).to_pylist()]\n\n\ndef _write_rows(path: Path, rows: Sequence[Mapping[str, Any]]) -> Path:\n    path.parent.mkdir(parents=True, exist_ok=True)\n    pq.write_table(pa.Table.from_pylist([dict(row) for row in rows]), path)\n    return path\n\n\ndef _write_rows_like(path: Path, rows: Sequence[Mapping[str, Any]]) -> Path:\n    schema = pq.read_table(path).schema\n    shaped = [{name: row.get(name) for name in schema.names} for row in rows]\n    if shaped:\n        table = pa.Table.from_pylist(shaped, schema=schema)\n    else:\n        table = pa.Table.from_arrays([pa.array([], type=field.type) for field in schema], schema=schema)\n    pq.write_table(table, path)\n    return path\n\n\ndef _append_unique_rows_like(path: Path, rows: Sequence[Mapping[str, Any]], *, id_column: str) -> Path:\n    incoming_ids = {str(row.get(id_column)) for row in rows if row.get(id_column) not in (None, "")}\n    existing = [row for row in _read_rows(path) if str(row.get(id_column)) not in incoming_ids]\n    return _write_rows_like(path, [*existing, *[dict(row) for row in rows]])\n\n\ndef _resolve_path(run_dir: Path, raw: Any, default: Path) -> Path:\n    if raw in (None, ""):\n        return run_dir / default\n    path = Path(str(raw))\n    if path.is_absolute() or path.exists():\n        return path\n    return run_dir / path\n\n\ndef _field_specs(manifest: Mapping[str, Any]) -> list[dict[str, Any]]:\n    specs = manifest.get("field_specs")\n    return [dict(item) for item in specs] if isinstance(specs, list) else []\n\n\ndef _covariate_specs(design_manifest: Mapping[str, Any], matrix_rows: Sequence[Mapping[str, Any]]) -> list[dict[str, str]]:\n    if not matrix_rows:\n        return []\n    columns = set(matrix_rows[0].keys())\n    specs: list[dict[str, str]] = []\n    for spec in _field_specs(design_manifest):\n        if spec.get("role") != "covariate":\n            continue\n        column = spec.get("column")\n        field_id = spec.get("field_id")\n        if column in columns and field_id not in (None, ""):\n            specs.append({"field_id": str(field_id), "column": str(column)})\n    if specs:\n        return specs\n    for column in sorted(str(col) for col in columns if str(col).startswith("covariate_")):\n        specs.append({"field_id": column, "column": column})\n    return specs\n\n\ndef _vector_from_rows(rows: Sequence[Mapping[str, Any]], preferred: Sequence[str]) -> list[float] | None:\n    if not rows:\n        return None\n    for name in preferred:\n        if name in rows[0]:\n            try:\n                return [float(row[name]) for row in rows]\n            except (TypeError, ValueError):\n                continue\n    return None\n\n\ndef _column_vector(rows: Sequence[Mapping[str, Any]], column: str) -> list[float] | None:\n    if not rows or column not in rows[0]:\n        return None\n    try:\n        return [float(row[column]) for row in rows]\n    except (TypeError, ValueError):\n        return None\n\n\ndef _fdr_bh(p_values: Sequence[float | None]) -> list[float | None]:\n    indexed = [(i, float(p)) for i, p in enumerate(p_values) if p is not None]\n    m = len(indexed)\n    out: list[float | None] = [None for _ in p_values]\n    if m == 0:\n        return out\n    ranked = sorted(indexed, key=lambda item: item[1])\n    running = 1.0\n    for rank_from_end, (idx, p) in enumerate(reversed(ranked), start=1):\n        rank = m - rank_from_end + 1\n        running = min(running, p * m / max(rank, 1))\n        out[idx] = min(1.0, max(0.0, running))\n    return out\n\n\ndef _scan_row(*, residual_field_id: str, model_id: str | None, covariate_field_id: str, covariate_column: str, residuals: Sequence[float], covariate: Sequence[float], budget: str, permutations: int, min_support: int, seed: int) -> dict[str, Any]:\n    n_eff = int(min(len(residuals), len(covariate)))\n    warnings: list[str] = []\n    statistic: float | None = None\n    p_value: float | None = None\n    mode = "exact_linear"\n    state = "verified"\n    if n_eff < min_support:\n        mode = "disabled"\n        state = "blocked"\n        warnings.append("hsic_disabled_insufficient_support")\n    else:\n        statistic = float(linear_hsic_statistic([float(v) for v in covariate[:n_eff]], [float(v) for v in residuals[:n_eff]]))\n        p_value = float(permutation_p_value(statistic=statistic, permutations=permutations, n_eff=n_eff))\n        if n_eff < 100:\n            state = "fragile"\n            warnings.append("hsic_descriptive_small_support")\n    hypothesis_id = f"hsic__{residual_field_id}__{covariate_field_id}"\n    return {\n        "hypothesis_id": hypothesis_id,\n        "model_id": model_id,\n        "residual_field_id": residual_field_id,\n        "covariate_field_id": covariate_field_id,\n        "covariate_column": covariate_column,\n        "hsic_mode": mode,\n        "budget": budget,\n        "n_eff": float(n_eff),\n        "statistic": statistic,\n        "p_value": p_value,\n        "q_value": None,\n        "state": state,\n        "warnings": warnings,\n        "permutations": int(permutations),\n        "seed": int(seed),\n        "kernel": "linear_centered",\n        "created_at": _now(),\n    }\n\n\ndef _hypothesis_row(row: Mapping[str, Any]) -> dict[str, Any]:\n    warnings = row.get("warnings") if isinstance(row.get("warnings"), list) else []\n    return {\n        "hypothesis_id": row.get("hypothesis_id"),\n        "outcome_field_id": row.get("residual_field_id"),\n        "exposure_field_id": row.get("covariate_field_id"),\n        "residual_field_id": row.get("residual_field_id"),\n        "method": "HSIC",\n        "statistic": row.get("statistic"),\n        "p_value": row.get("p_value"),\n        "q_value": row.get("q_value"),\n        "state": row.get("state", "fragile"),\n        "warnings": _compact(warnings),\n        "metadata_json": _compact(dict(row)),\n        "created_at": row.get("created_at") or _now(),\n    }\n\n\ndef _warning_rows(rows: Sequence[Mapping[str, Any]]) -> list[dict[str, Any]]:\n    out: list[dict[str, Any]] = []\n    for row in rows:\n        for i, code in enumerate(row.get("warnings") or [], start=1):\n            out.append({\n                "warning_id": f"slice18a_{row.get(\'hypothesis_id\')}_{i}",\n                "field_id": row.get("residual_field_id"),\n                "source": "PIRS-HSIC",\n                "severity": "warning",\n                "code": str(code),\n                "message": str(code).replace("_", " "),\n                "inherited_from": "[]",\n                "created_at": _now(),\n            })\n    return out\n\n\ndef _blocking_manifest(*, run_dir: Path, manifest_path: Path, reasons: Sequence[str]) -> dict[str, Any]:\n    payload = {\n        "schema_version": "1.0",\n        "slice": "18A",\n        "artifact": "hsic_residual_scan_manifest",\n        "status": "blocked",\n        "run_dir": str(run_dir),\n        "manifest_path": str(manifest_path),\n        "hypothesis_count": 0,\n        "score_count": 0,\n        "mutated_output_bundle": False,\n        "blocking_reasons": list(dict.fromkeys(str(reason) for reason in reasons)),\n        "created_at": _now(),\n    }\n    _write_json(manifest_path, payload)\n    return payload\n\n\ndef build_hsic_residual_scan_manifest(*, run_dir: str | Path, model_execution_manifest: str | Path | Mapping[str, Any] | None = None, design_matrix_manifest: str | Path | Mapping[str, Any] | None = None, output_manifest: str | Path | None = None, budget: str = "fast", permutations: int = 199, min_support: int = 3, seed: int = 20260613, mutate_output_bundle: bool = True, validate: bool = True) -> dict[str, Any]:\n    root = Path(run_dir)\n    manifest_path = Path(output_manifest) if output_manifest is not None else root / DEFAULT_HSIC_MANIFEST\n    model_manifest_path = Path(model_execution_manifest) if isinstance(model_execution_manifest, (str, Path)) else root / DEFAULT_MODEL_MANIFEST\n    design_manifest_path = Path(design_matrix_manifest) if isinstance(design_matrix_manifest, (str, Path)) else root / DEFAULT_DESIGN_MANIFEST\n    model_manifest = dict(model_execution_manifest) if isinstance(model_execution_manifest, Mapping) else _load_json(model_manifest_path)\n    design_manifest = dict(design_matrix_manifest) if isinstance(design_matrix_manifest, Mapping) else _load_json(design_manifest_path)\n\n    reasons: list[str] = []\n    if model_manifest.get("status") != "fitted":\n        reasons.append(f"model_execution_not_fitted:{model_manifest.get(\'status\', \'missing\')}")\n    residual_field_id = model_manifest.get("residual_field_id")\n    if residual_field_id in (None, ""):\n        reasons.append("residual_field_id_missing")\n    residual_path = _resolve_path(root, model_manifest.get("residual_values_path"), DEFAULT_RESIDUAL_VALUES)\n    if not residual_path.exists():\n        reasons.append(f"residual_values_missing:{residual_path}")\n    matrix_path = _resolve_path(root, design_manifest.get("matrix_path"), DEFAULT_DESIGN_MATRIX)\n    if not matrix_path.exists():\n        reasons.append(f"design_matrix_missing:{matrix_path}")\n    if reasons:\n        return _blocking_manifest(run_dir=root, manifest_path=manifest_path, reasons=reasons)\n\n    residual_rows = _read_rows(residual_path)\n    matrix_rows = _read_rows(matrix_path)\n    residual_vector = _vector_from_rows(residual_rows, ("standardized_residual", "residual", "value", "values"))\n    if residual_vector is None:\n        return _blocking_manifest(run_dir=root, manifest_path=manifest_path, reasons=["residual_vector_not_numeric"])\n    covariates = _covariate_specs(design_manifest, matrix_rows)\n    if not covariates:\n        return _blocking_manifest(run_dir=root, manifest_path=manifest_path, reasons=["no_covariates_available_for_hsic"])\n\n    scan_rows: list[dict[str, Any]] = []\n    for spec in covariates:\n        vector = _column_vector(matrix_rows, spec["column"])\n        if vector is None:\n            scan_rows.append({\n                "hypothesis_id": f"hsic__{residual_field_id}__{spec[\'field_id\']}",\n                "model_id": model_manifest.get("model_id"),\n                "residual_field_id": str(residual_field_id),\n                "covariate_field_id": spec["field_id"],\n                "covariate_column": spec["column"],\n                "hsic_mode": "blocked",\n                "budget": budget,\n                "n_eff": 0.0,\n                "statistic": None,\n                "p_value": None,\n                "q_value": None,\n                "state": "blocked",\n                "warnings": ["covariate_vector_not_numeric"],\n                "permutations": int(permutations),\n                "seed": int(seed),\n                "kernel": "linear_centered",\n                "created_at": _now(),\n            })\n            continue\n        scan_rows.append(_scan_row(residual_field_id=str(residual_field_id), model_id=model_manifest.get("model_id"), covariate_field_id=spec["field_id"], covariate_column=spec["column"], residuals=residual_vector, covariate=vector, budget=budget, permutations=permutations, min_support=min_support, seed=seed))\n\n    q_values = _fdr_bh([row.get("p_value") for row in scan_rows])\n    for row, q_value in zip(scan_rows, q_values):\n        row["q_value"] = q_value\n\n    _write_rows(root / DEFAULT_HSIC_SCORES, scan_rows)\n    payload = {\n        "schema_version": "1.0",\n        "slice": "18A",\n        "artifact": "hsic_residual_scan_manifest",\n        "status": "scanned" if scan_rows else "blocked",\n        "run_dir": str(root),\n        "manifest_path": str(manifest_path),\n        "source_model_execution_manifest": str(model_manifest_path),\n        "source_design_matrix_manifest": str(design_manifest_path),\n        "residual_field_id": str(residual_field_id),\n        "model_id": model_manifest.get("model_id"),\n        "budget": budget,\n        "permutations": int(permutations),\n        "min_support": int(min_support),\n        "score_path": str(root / DEFAULT_HSIC_SCORES),\n        "score_count": len(scan_rows),\n        "hypothesis_count": len(scan_rows),\n        "blocked_count": sum(1 for row in scan_rows if row.get("state") == "blocked"),\n        "fragile_count": sum(1 for row in scan_rows if row.get("state") == "fragile"),\n        "verified_count": sum(1 for row in scan_rows if row.get("state") == "verified"),\n        "mutated_output_bundle": bool(mutate_output_bundle),\n        "blocking_reasons": [],\n        "scan_rows": scan_rows,\n        "created_at": _now(),\n    }\n    if mutate_output_bundle:\n        _append_unique_rows_like(root / "Hypotheses.parquet", [_hypothesis_row(row) for row in scan_rows], id_column="hypothesis_id")\n        warnings = _warning_rows(scan_rows)\n        if warnings:\n            _append_unique_rows_like(root / "Warnings.parquet", warnings, id_column="warning_id")\n        if validate:\n            try:\n                from pegasus.output.validate import validate_output_bundle\n                validation = validate_output_bundle(run_dir=str(root))\n            except TypeError:\n                from pegasus.output.validate import validate_output_bundle\n                validation = validate_output_bundle(run_dir=str(root), schema_registry=None)  # type: ignore[arg-type]\n            payload["output_validation"] = {"ok": bool(validation.ok), "errors": list(getattr(validation, "errors", []) or [])}\n    _write_json(manifest_path, payload)\n    return payload\n\n\ndef hsic_residual_scan_summary(payload: Mapping[str, Any], *, manifest_path: str | Path | None = None) -> dict[str, Any]:\n    return {\n        "schema_version": "1.0",\n        "slice": "18A",\n        "gate": HSIC_GATE_KEY,\n        "status": payload.get("status"),\n        "residual_field_id": payload.get("residual_field_id"),\n        "model_id": payload.get("model_id"),\n        "score_count": int(payload.get("score_count") or 0),\n        "hypothesis_count": int(payload.get("hypothesis_count") or 0),\n        "blocked_count": int(payload.get("blocked_count") or 0),\n        "fragile_count": int(payload.get("fragile_count") or 0),\n        "verified_count": int(payload.get("verified_count") or 0),\n        "mutated_output_bundle": bool(payload.get("mutated_output_bundle")),\n        "blocking_reason_count": len(payload.get("blocking_reasons") or []),\n        "manifest_path": str(manifest_path) if manifest_path is not None else payload.get("manifest_path"),\n        "score_path": payload.get("score_path"),\n        "output_validation": payload.get("output_validation"),\n    }\n\n\ndef attach_hsic_residual_scan_gate_to_run(*, run_dir: str | Path, summary: Mapping[str, Any]) -> None:\n    root = Path(run_dir)\n    for rel in JSON_ATTACH_TARGETS:\n        path = root / rel\n        doc = _load_json(path)\n        doc[HSIC_GATE_KEY] = dict(summary)\n        if rel == "ReproducibilityManifest.json":\n            pirs = doc.setdefault("pirs", {})\n            if isinstance(pirs, dict):\n                pirs["hsic_residual_scan"] = dict(summary)\n            telemetry = doc.setdefault("telemetry", {})\n            if isinstance(telemetry, dict):\n                stage_status = telemetry.setdefault("stage_status", {})\n                if isinstance(stage_status, dict):\n                    stage_status["pirs_hsic"] = "success" if summary.get("status") == "scanned" else "blocked"\n        _write_json(path, doc)\n\n\ndef execute_hsic_residual_scan(*, run_dir: str | Path, model_execution_manifest: str | Path | Mapping[str, Any] | None = None, design_matrix_manifest: str | Path | Mapping[str, Any] | None = None, output_manifest: str | Path | None = None, budget: str = "fast", permutations: int = 199, min_support: int = 3, seed: int = 20260613, mutate_output_bundle: bool = True, validate: bool = True, attach: bool = True) -> dict[str, Any]:\n    payload = build_hsic_residual_scan_manifest(run_dir=run_dir, model_execution_manifest=model_execution_manifest, design_matrix_manifest=design_matrix_manifest, output_manifest=output_manifest, budget=budget, permutations=permutations, min_support=min_support, seed=seed, mutate_output_bundle=mutate_output_bundle, validate=validate)\n    summary = hsic_residual_scan_summary(payload, manifest_path=payload.get("manifest_path"))\n    payload["summary"] = summary\n    _write_json(Path(str(payload["manifest_path"])), payload)\n    if attach:\n        attach_hsic_residual_scan_gate_to_run(run_dir=run_dir, summary=summary)\n    return {"manifest_path": payload["manifest_path"], HSIC_GATE_KEY: summary, "hsic_residual_scan": payload}\n\n\ndef inspect_hsic_residual_scan_manifest(manifest: str | Path) -> dict[str, Any]:\n    payload = _load_json(Path(manifest))\n    if not payload:\n        raise FileNotFoundError(f"missing or invalid HSIC residual scan manifest: {manifest}")\n    summary = payload.get("summary")\n    if isinstance(summary, Mapping):\n        return dict(summary)\n    return hsic_residual_scan_summary(payload, manifest_path=manifest)\n'
WORKFLOW = '\n"""Workflow wrappers for run-bundle HSIC residual scanning."""\n\nfrom __future__ import annotations\n\nfrom pathlib import Path\nfrom typing import Any, Mapping\n\nfrom pegasus.pirs.hsic_run import execute_hsic_residual_scan, inspect_hsic_residual_scan_manifest\n\n\ndef run_execute_hsic_residual_scan(*, run_dir: str | Path, model_execution_manifest: str | Path | Mapping[str, Any] | None = None, design_matrix_manifest: str | Path | Mapping[str, Any] | None = None, output_manifest: str | Path | None = None, budget: str = "fast", permutations: int = 199, min_support: int = 3, seed: int = 20260613, mutate_output_bundle: bool = True, validate: bool = True, attach: bool = True) -> dict[str, Any]:\n    return execute_hsic_residual_scan(run_dir=run_dir, model_execution_manifest=model_execution_manifest, design_matrix_manifest=design_matrix_manifest, output_manifest=output_manifest, budget=budget, permutations=permutations, min_support=min_support, seed=seed, mutate_output_bundle=mutate_output_bundle, validate=validate, attach=attach)\n\n\ndef run_inspect_hsic_residual_scan(*, manifest: str | Path) -> dict[str, Any]:\n    return inspect_hsic_residual_scan_manifest(manifest)\n'
CLI_BLOCK = '\n\n# ---- Slice 18A HSIC residual scan CLI boundary ----\n@pirs_app.command("scan-residuals-hsic")\ndef pirs_scan_residuals_hsic(\n    run_dir: Path = typer.Option(..., "--run-dir"),\n    model_execution_manifest: Path | None = typer.Option(None, "--model-execution-manifest"),\n    design_matrix_manifest: Path | None = typer.Option(None, "--design-matrix-manifest"),\n    output_manifest: Path | None = typer.Option(None, "--output-manifest"),\n    budget: str = typer.Option("fast", "--budget"),\n    permutations: int = typer.Option(199, "--permutations"),\n    min_support: int = typer.Option(3, "--min-support"),\n    mutate_output_bundle: bool = typer.Option(True, "--mutate-output-bundle/--no-mutate-output-bundle"),\n    validate: bool = typer.Option(True, "--validate/--no-validate"),\n    attach: bool = typer.Option(True, "--attach/--no-attach"),\n) -> None:\n    """Scan PIRS residuals against design covariates with HSIC and emit hypothesis rows."""\n    from pegasus.workflows.hsic_execute import run_execute_hsic_residual_scan\n\n    _pirs_cli_print(run_execute_hsic_residual_scan(run_dir=run_dir, model_execution_manifest=model_execution_manifest, design_matrix_manifest=design_matrix_manifest, output_manifest=output_manifest, budget=budget, permutations=permutations, min_support=min_support, mutate_output_bundle=mutate_output_bundle, validate=validate, attach=attach))\n\n\n@pirs_app.command("inspect-hsic-scan")\ndef pirs_inspect_hsic_scan(\n    manifest: Path = typer.Option(..., "--manifest"),\n) -> None:\n    """Read an existing HSIC residual-scan manifest without mutating a run."""\n    from pegasus.workflows.hsic_execute import run_inspect_hsic_residual_scan\n\n    _pirs_cli_print(run_inspect_hsic_residual_scan(manifest=manifest))\n# ---- End Slice 18A HSIC residual scan CLI boundary ----\n'
UNIT_TEST = '\nfrom __future__ import annotations\n\nfrom pegasus.pirs.hsic_run import _covariate_specs, _fdr_bh, hsic_residual_scan_summary\n\n\ndef test_slice18a_fdr_is_monotone_and_bounded() -> None:\n    q = _fdr_bh([0.01, 0.20, None, 0.03])\n    assert q[0] is not None and 0.0 <= q[0] <= 1.0\n    assert q[2] is None\n    assert q[0] <= q[3] <= q[1]\n\n\ndef test_slice18a_covariate_specs_respect_design_manifest() -> None:\n    rows = [{"response": 1.0, "covariate_001": 2.0, "covariate_002": 3.0}]\n    manifest = {"field_specs": [{"field_id": "capacity", "role": "covariate", "column": "covariate_001"}]}\n    assert _covariate_specs(manifest, rows) == [{"field_id": "capacity", "column": "covariate_001"}]\n\n\ndef test_slice18a_summary_reports_blocked_manifest_path() -> None:\n    summary = hsic_residual_scan_summary({"status": "blocked", "blocking_reasons": ["x"], "manifest_path": "m.json"})\n    assert summary["status"] == "blocked"\n    assert summary["blocking_reason_count"] == 1\n    assert summary["manifest_path"] == "m.json"\n'
INTEGRATION_TEST = '\nfrom __future__ import annotations\n\nimport json\nfrom pathlib import Path\n\nimport pyarrow as pa\nimport pyarrow.parquet as pq\nfrom typer.testing import CliRunner\n\nfrom pegasus.cli import app\nfrom pegasus.output.bundle import create_empty_output_bundle\nfrom pegasus.output.validate import validate_output_bundle\nfrom pegasus.workflows.pirs_execute import run_execute_pirs_model\nfrom pegasus.workflows.hsic_execute import run_execute_hsic_residual_scan\n\n\ndef _write_json(path: Path, payload: dict) -> None:\n    path.parent.mkdir(parents=True, exist_ok=True)\n    path.write_text(json.dumps(payload, ensure_ascii=False, sort_keys=True, indent=2), encoding="utf-8")\n\n\ndef _ready_modeled_run(run_dir: Path) -> None:\n    create_empty_output_bundle(run_dir)\n    matrix = run_dir / "Tables" / "pirs_design_matrix.parquet"\n    pq.write_table(pa.Table.from_pylist([\n        {"row_id": 0, "intercept": 1.0, "response": 10.0, "covariate_001": 1.0, "covariate_002": 4.0},\n        {"row_id": 1, "intercept": 1.0, "response": 12.0, "covariate_001": 2.0, "covariate_002": 3.0},\n        {"row_id": 2, "intercept": 1.0, "response": 13.0, "covariate_001": 3.0, "covariate_002": 2.0},\n        {"row_id": 3, "intercept": 1.0, "response": 17.0, "covariate_001": 4.0, "covariate_002": 1.0},\n    ]), matrix)\n    _write_json(run_dir / "Tables" / "pirs_design_matrix_manifest.json", {\n        "status": "ready",\n        "matrix_written": True,\n        "matrix_path": str(matrix),\n        "family": "gaussian_identity",\n        "residual_mode": "in_sample",\n        "fold_scheme": "none_in_sample_fast_budget",\n        "field_specs": [\n            {"field_id": "deaths", "role": "outcome", "column": "response"},\n            {"field_id": "capacity_a", "role": "covariate", "column": "covariate_001"},\n            {"field_id": "capacity_b", "role": "covariate", "column": "covariate_002"},\n        ],\n    })\n    run_execute_pirs_model(run_dir=run_dir)\n\n\ndef test_slice18a_scans_residuals_writes_hypotheses_and_validates(tmp_path: Path) -> None:\n    run_dir = tmp_path / "run"\n    _ready_modeled_run(run_dir)\n    result = run_execute_hsic_residual_scan(run_dir=run_dir)\n    gate = result["hsic_residual_scan_gate"]\n    assert gate["status"] == "scanned"\n    assert gate["hypothesis_count"] == 2\n    assert (run_dir / "Tables" / "hsic_residual_scan_scores.parquet").exists()\n    assert (run_dir / "Tables" / "hsic_residual_scan_manifest.json").exists()\n    validation = validate_output_bundle(run_dir=str(run_dir))\n    assert validation.ok, validation.errors\n    hypotheses = pq.read_table(run_dir / "Hypotheses.parquet").to_pylist()\n    assert len(hypotheses) == 2\n    assert {row["method"] for row in hypotheses} == {"HSIC"}\n    repro = json.loads((run_dir / "ReproducibilityManifest.json").read_text(encoding="utf-8"))\n    assert repro["hsic_residual_scan_gate"]["status"] == "scanned"\n    assert repro["telemetry"]["stage_status"]["pirs_hsic"] == "success"\n\n\ndef test_slice18a_cli_scans_and_inspects(tmp_path: Path) -> None:\n    run_dir = tmp_path / "run_cli"\n    _ready_modeled_run(run_dir)\n    runner = CliRunner()\n    result = runner.invoke(app, ["pirs", "scan-residuals-hsic", "--run-dir", str(run_dir)])\n    assert result.exit_code == 0, result.output\n    assert \'"status": "scanned"\' in result.output\n    manifest = run_dir / "Tables" / "hsic_residual_scan_manifest.json"\n    result = runner.invoke(app, ["pirs", "inspect-hsic-scan", "--manifest", str(manifest)])\n    assert result.exit_code == 0, result.output\n    assert \'"hypothesis_count": 2\' in result.output\n'
AUDIT = '\nfrom __future__ import annotations\n\nimport ast\nimport json\nimport tempfile\nfrom pathlib import Path\n\nimport pyarrow as pa\nimport pyarrow.parquet as pq\n\nfrom pegasus.output.bundle import create_empty_output_bundle\nfrom pegasus.output.validate import validate_output_bundle\nfrom pegasus.workflows.pirs_execute import run_execute_pirs_model\nfrom pegasus.workflows.hsic_execute import run_execute_hsic_residual_scan\n\n\ndef _count_defs(path: Path, name: str) -> int:\n    tree = ast.parse(path.read_text(encoding="utf-8"))\n    return sum(1 for node in tree.body if isinstance(node, ast.FunctionDef) and node.name == name)\n\n\ndef _write_json(path: Path, payload: dict) -> None:\n    path.parent.mkdir(parents=True, exist_ok=True)\n    path.write_text(json.dumps(payload, ensure_ascii=False, sort_keys=True, indent=2), encoding="utf-8")\n\n\ndef main() -> int:\n    errors: list[str] = []\n    if _count_defs(Path("src/pegasus/workflows/compile.py"), "run_compile") != 1:\n        errors.append("compile.py public run_compile count changed")\n    if _count_defs(Path("src/pegasus/pirs/hsic_run.py"), "build_hsic_residual_scan_manifest") != 1:\n        errors.append("HSIC run builder API missing")\n    cli = Path("src/pegasus/cli.py").read_text(encoding="utf-8")\n    if \'@pirs_app.command("scan-residuals-hsic")\' not in cli:\n        errors.append("CLI scan-residuals-hsic command missing")\n    with tempfile.TemporaryDirectory() as tmp:\n        run_dir = Path(tmp) / "run"\n        create_empty_output_bundle(run_dir)\n        matrix = run_dir / "Tables" / "pirs_design_matrix.parquet"\n        pq.write_table(pa.Table.from_pylist([\n            {"row_id": 0, "intercept": 1.0, "response": 1.0, "covariate_001": 0.0},\n            {"row_id": 1, "intercept": 1.0, "response": 2.5, "covariate_001": 1.0},\n            {"row_id": 2, "intercept": 1.0, "response": 2.7, "covariate_001": 2.0},\n            {"row_id": 3, "intercept": 1.0, "response": 4.8, "covariate_001": 3.0},\n        ]), matrix)\n        _write_json(run_dir / "Tables" / "pirs_design_matrix_manifest.json", {"status": "ready", "matrix_written": True, "matrix_path": str(matrix), "family": "gaussian_identity", "field_specs": [{"field_id": "outcome", "role": "outcome", "column": "response"}, {"field_id": "cov", "role": "covariate", "column": "covariate_001"}]})\n        run_execute_pirs_model(run_dir=run_dir)\n        result = run_execute_hsic_residual_scan(run_dir=run_dir)\n        gate = result.get("hsic_residual_scan_gate", {})\n        if gate.get("status") != "scanned":\n            errors.append("synthetic run was not scanned")\n        validation = validate_output_bundle(run_dir=str(run_dir))\n        if not validation.ok:\n            errors.append("output bundle invalid after HSIC scan: " + "; ".join(validation.errors))\n        for rel in ("Tables/hsic_residual_scan_manifest.json", "Tables/hsic_residual_scan_scores.parquet"):\n            if not (run_dir / rel).exists():\n                errors.append(f"missing HSIC artifact: {rel}")\n        hypotheses = pq.read_table(run_dir / "Hypotheses.parquet").to_pylist()\n        if not hypotheses or hypotheses[0].get("method") != "HSIC":\n            errors.append("HSIC hypothesis rows missing")\n    print(json.dumps({"ok": not errors, "errors": errors}, ensure_ascii=False, sort_keys=True, indent=2))\n    if errors:\n        return 1\n    print("AUDIT PASSED: Slice 18A HSIC residual scan integration")\n    return 0\n\n\nif __name__ == "__main__":\n    raise SystemExit(main())\n'


def fail(message: str) -> None:
    raise SystemExit(f"[slice18a] {message}")


def read(path: str) -> str:
    p = ROOT / path
    if not p.exists():
        fail(f"required file missing: {path}")
    return p.read_text(encoding="utf-8")


def write(path: str, text: str) -> None:
    if path.startswith(FORBIDDEN_PREFIXES):
        fail(f"refusing to write forbidden path: {path}")
    p = ROOT / path
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(text.rstrip() + "\n", encoding="utf-8")


def top_level_function_count(text: str, name: str) -> int:
    tree = ast.parse(text)
    return sum(1 for node in tree.body if isinstance(node, ast.FunctionDef) and node.name == name)


def preflight() -> None:
    required = (
        "src/pegasus/pirs/hsic.py",
        "src/pegasus/pirs/model_execution.py",
        "src/pegasus/workflows/pirs_execute.py",
        "src/pegasus/cli.py",
    )
    for path in required:
        if not (ROOT / path).exists():
            fail(f"required preflight file missing: {path}")
    compile_text = read("src/pegasus/workflows/compile.py")
    if top_level_function_count(compile_text, "run_compile") != 1:
        fail("compile.py must still contain exactly one public run_compile")
    if top_level_function_count(compile_text, "_run_compile_impl") != 1:
        fail("compile.py must still contain exactly one private _run_compile_impl")
    if "execute_pirs_model_from_design_matrix" not in read("src/pegasus/pirs/model_execution.py"):
        fail("Slice 17B model execution boundary not detected")
    cli = read("src/pegasus/cli.py")
    if "pirs_app = typer.Typer" not in cli or 'app.add_typer(pirs_app, name="pirs")' not in cli:
        fail("cli.py does not expose pirs_app")


def strip_existing_block(text: str) -> str:
    start = text.find(MARKER_START)
    if start == -1:
        return text
    end = text.find(MARKER_END, start)
    if end == -1:
        return text[:start].rstrip() + "\n"
    end_line = text.find("\n", end)
    if end_line == -1:
        return text[:start].rstrip() + "\n"
    return (text[:start] + text[end_line + 1:]).rstrip() + "\n"


def patch_cli() -> None:
    path = "src/pegasus/cli.py"
    text = strip_existing_block(read(path))
    if "def _pirs_cli_print" not in text:
        fail("cli.py missing _pirs_cli_print helper")
    if "pirs_app = typer.Typer" not in text:
        fail("cli.py missing pirs_app")
    text = text.rstrip() + CLI_BLOCK
    for token in ('@pirs_app.command("scan-residuals-hsic")', '@pirs_app.command("inspect-hsic-scan")'):
        if token not in text:
            fail(f"cli patch missing token: {token}")
    write(path, text)


def write_files() -> None:
    write("src/pegasus/pirs/hsic_run.py", HSIC_RUN)
    write("src/pegasus/workflows/hsic_execute.py", WORKFLOW)
    patch_cli()
    write("tests/unit/test_slice18a_hsic_residual_scan_integration.py", UNIT_TEST)
    write("tests/integration/test_slice18a_hsic_residual_scan_integration.py", INTEGRATION_TEST)
    write("scripts/dev/audits/audit_slice18a_hsic_residual_scan_integration.py", AUDIT)


def self_validate() -> None:
    for path in TOUCH_LIST:
        py_compile.compile(str(ROOT / path), doraise=True)
    src = str(ROOT / "src")
    if src not in sys.path:
        sys.path.insert(0, src)
    from pegasus.pirs.hsic_run import build_hsic_residual_scan_manifest
    from pegasus.workflows.hsic_execute import run_execute_hsic_residual_scan
    if not callable(build_hsic_residual_scan_manifest) or not callable(run_execute_hsic_residual_scan):
        fail("post-validate: HSIC residual scan APIs not callable")


def main() -> None:
    preflight()
    write_files()
    self_validate()
    print("Slice 18A updater applied: HSIC residual scan integration, hypothesis materialization, and CLI added.")
    print("Touched files:")
    for path in TOUCH_LIST:
        print(f"  - {path}")


if __name__ == "__main__":
    main()
